// src/components/WorkoutCalendar.js
import React, { useState, useMemo } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ScrollView,
  Modal,
  SafeAreaView,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';

const WorkoutCalendar = ({ workoutHistory, onWorkoutPress }) => {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedWorkout, setSelectedWorkout] = useState(null);
  const [showWorkoutModal, setShowWorkoutModal] = useState(false);

  // Get workout rating colors
  const getRatingColor = (rating) => {
    if (rating >= 9) return '#22c55e'; // Bright green - Excellent
    if (rating >= 7) return '#84cc16'; // Light green - Great
    if (rating >= 5) return '#eab308'; // Yellow - Good
    if (rating >= 3) return '#f97316'; // Orange - Poor
    return '#ef4444'; // Red - Terrible
  };

  // Get workout rating text
  const getRatingText = (rating) => {
    if (rating >= 9) return 'Excellent';
    if (rating >= 7) return 'Great';
    if (rating >= 5) return 'Good';
    if (rating >= 3) return 'Poor';
    return 'Terrible';
  };

  // Generate workouts by date map
  const workoutsByDate = useMemo(() => {
    const map = {};
    workoutHistory.forEach(workout => {
      const date = new Date(workout.startTime);
      const dateKey = `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
      if (!map[dateKey]) {
        map[dateKey] = [];
      }
      map[dateKey].push(workout);
    });
    return map;
  }, [workoutHistory]);

  // Calendar generation
  const generateCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    
    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - firstDay.getDay()); // Start from Sunday
    
    const endDate = new Date(lastDay);
    endDate.setDate(endDate.getDate() + (6 - lastDay.getDay())); // End on Saturday
    
    const weeks = [];
    const currentWeekDate = new Date(startDate);
    
    while (currentWeekDate <= endDate) {
      const week = [];
      for (let i = 0; i < 7; i++) {
        const date = new Date(currentWeekDate);
        const dateKey = `${date.getFullYear()}-${date.getMonth()}-${date.getDate()}`;
        const dayWorkouts = workoutsByDate[dateKey] || [];
        
        week.push({
          date: new Date(date),
          workouts: dayWorkouts,
          isCurrentMonth: date.getMonth() === month,
          isToday: 
            date.getDate() === new Date().getDate() &&
            date.getMonth() === new Date().getMonth() &&
            date.getFullYear() === new Date().getFullYear(),
        });
        
        currentWeekDate.setDate(currentWeekDate.getDate() + 1);
      }
      weeks.push(week);
    }
    
    return weeks;
  };

  const calendar = generateCalendar();

  const goToPreviousMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const goToNextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const openWorkoutDetail = (workout) => {
    setSelectedWorkout(workout);
    setShowWorkoutModal(true);
  };

  const renderWorkoutModal = () => (
    <Modal
      visible={showWorkoutModal}
      transparent={true}
      animationType="slide"
    >
      <View style={styles.modalOverlay}>
        <SafeAreaView style={styles.modalContainer}>
          <View style={styles.modalContent}>
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>Workout Details</Text>
              <TouchableOpacity 
                onPress={() => setShowWorkoutModal(false)}
                style={styles.closeButton}
              >
                <Ionicons name="close" size={24} color="#666" />
              </TouchableOpacity>
            </View>
            
            {selectedWorkout && (
              <ScrollView style={styles.modalBody}>
                <View style={styles.workoutSummary}>
                  <Text style={styles.workoutDate}>
                    {new Date(selectedWorkout.startTime).toLocaleDateString('en-US', {
                      weekday: 'long',
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric'
                    })}
                  </Text>
                  <Text style={styles.workoutTime}>
                    {new Date(selectedWorkout.startTime).toLocaleTimeString('en-US', {
                      hour: 'numeric',
                      minute: '2-digit'
                    })} - {new Date(selectedWorkout.endTime).toLocaleTimeString('en-US', {
                      hour: 'numeric',
                      minute: '2-digit'
                    })}
                  </Text>
                  <Text style={styles.workoutDuration}>
                    Duration: {selectedWorkout.duration} minutes
                  </Text>
                </View>

                <View style={styles.ratingsSection}>
                  <Text style={styles.sectionTitle}>Ratings</Text>
                  <View style={styles.ratingsGrid}>
                    <View style={styles.ratingItem}>
                      <Text style={styles.ratingLabel}>Pre-Mood</Text>
                      <Text style={styles.ratingValue}>{selectedWorkout.ratings.beforeMood}/10</Text>
                    </View>
                    <View style={styles.ratingItem}>
                      <Text style={styles.ratingLabel}>Pre-Energy</Text>
                      <Text style={styles.ratingValue}>{selectedWorkout.ratings.beforeEnergy}/10</Text>
                    </View>
                    <View style={styles.ratingItem}>
                      <Text style={styles.ratingLabel}>Post-Mood</Text>
                      <Text style={styles.ratingValue}>{selectedWorkout.ratings.afterMood}/10</Text>
                    </View>
                    <View style={styles.ratingItem}>
                      <Text style={styles.ratingLabel}>Post-Energy</Text>
                      <Text style={styles.ratingValue}>{selectedWorkout.ratings.afterEnergy}/10</Text>
                    </View>
                  </View>
                  <View style={[styles.overallRating, { backgroundColor: getRatingColor(selectedWorkout.ratings.workoutRating) }]}>
                    <Text style={styles.overallRatingText}>
                      Overall: {selectedWorkout.ratings.workoutRating}/10 - {getRatingText(selectedWorkout.ratings.workoutRating)}
                    </Text>
                  </View>
                </View>

                <View style={styles.exercisesSection}>
                  <Text style={styles.sectionTitle}>Exercises ({selectedWorkout.exercises.length})</Text>
                  {selectedWorkout.exercises.map((exercise, index) => (
                    <View key={exercise.id} style={styles.exerciseItem}>
                      <Text style={styles.exerciseName}>
                        {index + 1}. {exercise.name}
                      </Text>
                      <Text style={styles.exerciseSets}>
                        {exercise.sets.filter(set => set.reps && set.weight).length} sets
                      </Text>
                      <View style={styles.setsContainer}>
                        {exercise.sets
                          .filter(set => set.reps && set.weight)
                          .map((set, setIndex) => (
                            <Text key={setIndex} style={styles.setDetail}>
                              {set.reps} reps × {set.weight} lbs
                            </Text>
                          ))}
                      </View>
                    </View>
                  ))}
                </View>
              </ScrollView>
            )}
          </View>
        </SafeAreaView>
      </View>
    </Modal>
  );

  return (
    <View style={styles.container}>
      {/* Calendar Header */}
      <View style={styles.header}>
        <TouchableOpacity onPress={goToPreviousMonth} style={styles.navButton}>
          <Ionicons name="chevron-back" size={24} color="#007AFF" />
        </TouchableOpacity>
        
        <Text style={styles.monthTitle}>
          {currentDate.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}
        </Text>
        
        <TouchableOpacity onPress={goToNextMonth} style={styles.navButton}>
          <Ionicons name="chevron-forward" size={24} color="#007AFF" />
        </TouchableOpacity>
      </View>

      {/* Days of Week Header */}
      <View style={styles.daysHeader}>
        {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
          <Text key={day} style={styles.dayHeader}>{day}</Text>
        ))}
      </View>

      {/* Calendar Grid */}
      <ScrollView style={styles.calendarContainer}>
        {calendar.map((week, weekIndex) => (
          <View key={weekIndex} style={styles.week}>
            {week.map((day, dayIndex) => (
              <View key={dayIndex} style={[
                styles.day,
                !day.isCurrentMonth && styles.otherMonth,
                day.isToday && styles.today
              ]}>
                <Text style={[
                  styles.dayNumber,
                  !day.isCurrentMonth && styles.otherMonthText,
                  day.isToday && styles.todayText
                ]}>
                  {day.date.getDate()}
                </Text>
                
                {/* Workout Indicators */}
                <View style={styles.workoutIndicators}>
                  {day.workouts.slice(0, 3).map((workout, workoutIndex) => (
                    <TouchableOpacity
                      key={workout.id}
                      style={[
                        styles.workoutDot,
                        { backgroundColor: getRatingColor(workout.ratings.workoutRating) }
                      ]}
                      onPress={() => openWorkoutDetail(workout)}
                    />
                  ))}
                  {day.workouts.length > 3 && (
                    <Text style={styles.moreWorkouts}>+{day.workouts.length - 3}</Text>
                  )}
                </View>
              </View>
            ))}
          </View>
        ))}
      </ScrollView>

      {/* Legend */}
      <View style={styles.legend}>
        <Text style={styles.legendTitle}>Workout Ratings:</Text>
        <View style={styles.legendItems}>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: '#22c55e' }]} />
            <Text style={styles.legendText}>9-10</Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: '#84cc16' }]} />
            <Text style={styles.legendText}>7-8</Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: '#eab308' }]} />
            <Text style={styles.legendText}>5-6</Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: '#f97316' }]} />
            <Text style={styles.legendText}>3-4</Text>
          </View>
          <View style={styles.legendItem}>
            <View style={[styles.legendDot, { backgroundColor: '#ef4444' }]} />
            <Text style={styles.legendText}>1-2</Text>
          </View>
        </View>
      </View>

      {renderWorkoutModal()}
    </View>
  );
};

